import { inflateRawSync, crc32 } from 'node:zlib';
export function extractSingleEntry(zip /* Buffer */) {
  // 1. EOCD 0x06054b50: scan back over the 22-B record plus a comment of up to 64 KiB
  let eocd = -1;
  for (let i = zip.length - 22; i >= Math.max(0, zip.length - 22 - 0xffff); i--)
    if (zip.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  if (eocd < 0) throw new Error('EOCD not found (truncated download / HTML error page)');
  if (eocd >= 20 && zip.readUInt32LE(eocd - 20) === 0x07064b50) throw new Error('ZIP64 unsupported');
  if (zip.readUInt16LE(eocd + 10) !== 1) throw new Error('expected exactly 1 entry');
  const cd = zip.readUInt32LE(eocd + 16);
  // 2. Central directory 0x02014b50: authoritative CRC and sizes (correct even if bit 3 were set)
  if (zip.readUInt32LE(cd) !== 0x02014b50) throw new Error('bad central header');
  const flags = zip.readUInt16LE(cd + 8), method = zip.readUInt16LE(cd + 10);
  const crc = zip.readUInt32LE(cd + 16), compSize = zip.readUInt32LE(cd + 20), size = zip.readUInt32LE(cd + 24);
  const nameLen = zip.readUInt16LE(cd + 28), loc = zip.readUInt32LE(cd + 42);
  const name = zip.toString('utf8', cd + 46, cd + 46 + nameLen);   // also check /^[A-Z0-9]+-1m-\d{4}-\d{2}(-\d{2})?\.csv$/
  if (flags & 1) throw new Error('encrypted');
  if ([compSize, size, loc].includes(0xffffffff)) throw new Error('ZIP64 unsupported');
  // 3. Local header 0x04034b50: use ITS OWN name/extra lengths to find the data
  if (zip.readUInt32LE(loc) !== 0x04034b50) throw new Error('bad local header');
  const data = loc + 30 + zip.readUInt16LE(loc + 26) + zip.readUInt16LE(loc + 28);
  if (data + compSize > cd) throw new Error('entry overlaps central directory');
  const raw = zip.subarray(data, data + compSize);
  // 4. Inflate (method 8) or copy (method 0), capping output (zip-bomb guard), then verify size and CRC-32
  let out;
  if (method === 8) out = inflateRawSync(raw, { maxOutputLength: Math.max(size, 1) });
  else if (method === 0) out = Buffer.from(raw);
  else throw new Error('unsupported method ' + method);
  if (out.length !== size || (crc32(out) >>> 0) !== crc) throw new Error('size/CRC-32 mismatch');
  return { name, csv: out };
}

